/**
 * Petrojam wholesale prices — Dominion Fuel Management → Prices
 * Sync latest page, year, month, or full archive from petrojam.com/price/
 */

import { Hono } from "https://deno.land/x/hono@v4.3.11/mod.ts";
import { cors } from "https://deno.land/x/hono@v4.3.11/middleware.ts";
import { createClient, type SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { requirePlatformAdmin } from "../_shared/platformAdmin.ts";
import {
  fetchPetrojamPrices,
  PETROJAM_PRICE_URL,
  type PetrojamFetchResult,
  type PetrojamPriceRow,
  type PetrojamSyncMode,
} from "./scrape.ts";

const app = new Hono().basePath("/petrojam-prices");

app.use("*", cors());

function logLine(payload: Record<string, unknown>) {
  console.log(JSON.stringify({ svc: "petrojam-prices", ts: new Date().toISOString(), ...payload }));
}

function svc(): SupabaseClient {
  return createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "",
  );
}

const ADMIN_WRITE_ROLES = new Set(["platform_owner", "superadmin", "rides_admin"]);

function rowToApi(r: Record<string, unknown>) {
  return {
    id: r.id,
    priceDate: r.price_date,
    gasolene87: r.gasolene_87 != null ? Number(r.gasolene_87) : null,
    gasolene90: r.gasolene_90 != null ? Number(r.gasolene_90) : null,
    autoDiesel: r.auto_diesel != null ? Number(r.auto_diesel) : null,
    kerosene: r.kerosene != null ? Number(r.kerosene) : null,
    propane: r.propane != null ? Number(r.propane) : null,
    butane: r.butane != null ? Number(r.butane) : null,
    hfo: r.hfo != null ? Number(r.hfo) : null,
    asphalt: r.asphalt != null ? Number(r.asphalt) : null,
    ulsd: r.ulsd != null ? Number(r.ulsd) : null,
    sourceUrl: r.source_url,
    scrapedAt: r.scraped_at,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

function toDbRow(row: PetrojamPriceRow, scrapedAt: string) {
  return {
    price_date: row.priceDate,
    gasolene_87: row.gasolene87,
    gasolene_90: row.gasolene90,
    auto_diesel: row.autoDiesel,
    kerosene: row.kerosene,
    propane: row.propane,
    butane: row.butane,
    hfo: row.hfo,
    asphalt: row.asphalt,
    ulsd: row.ulsd,
    source_url: PETROJAM_PRICE_URL,
    scraped_at: scrapedAt,
    updated_at: scrapedAt,
  };
}

async function upsertScraped(
  scraped: PetrojamPriceRow[],
  scrapedAt: string,
): Promise<{ inserted: number; updated: number }> {
  const db = svc();
  const dates = scraped.map((r) => r.priceDate);

  // Chunk existing lookups / upserts for large archive syncs
  const existingSet = new Set<string>();
  for (let i = 0; i < dates.length; i += 200) {
    const slice = dates.slice(i, i + 200);
    const { data: existing, error: existingErr } = await db
      .from("fuel_petrojam_prices")
      .select("price_date")
      .in("price_date", slice);
    if (existingErr) throw new Error(existingErr.message);
    for (const r of existing ?? []) {
      existingSet.add((r as { price_date: string }).price_date);
    }
  }

  const payload = scraped.map((r) => toDbRow(r, scrapedAt));
  for (let i = 0; i < payload.length; i += 100) {
    const slice = payload.slice(i, i + 100);
    const { error: upsertErr } = await db.from("fuel_petrojam_prices").upsert(slice, {
      onConflict: "price_date",
    });
    if (upsertErr) throw new Error(upsertErr.message);
  }

  let inserted = 0;
  let updated = 0;
  for (const d of dates) {
    if (existingSet.has(d)) updated += 1;
    else inserted += 1;
  }
  return { inserted, updated };
}

app.get("/health", (c) => {
  return c.json({
    service: "petrojam-prices",
    status: "ok",
    source: PETROJAM_PRICE_URL,
    syncModes: ["latest", "year", "month", "all"],
  });
});

app.get("/admin/prices", async (c) => {
  const auth = await requirePlatformAdmin(c);
  if (auth instanceof Response) return auth;

  const limitRaw = Number(c.req.query("limit") || 104);
  const limit = Number.isFinite(limitRaw) ? Math.min(Math.max(limitRaw, 1), 1000) : 104;
  const yearRaw = c.req.query("year");
  const monthRaw = c.req.query("month");
  const year = yearRaw ? Number(yearRaw) : null;
  const month = monthRaw ? Number(monthRaw) : null;

  const db = svc();
  let q = db.from("fuel_petrojam_prices").select("*").order("price_date", { ascending: false }).limit(limit);

  if (year && Number.isFinite(year)) {
    if (month && month >= 1 && month <= 12) {
      const monthStart = `${year}-${String(month).padStart(2, "0")}-01`;
      const lastDay = new Date(Date.UTC(year, month, 0)).getUTCDate();
      const monthEnd = `${year}-${String(month).padStart(2, "0")}-${String(lastDay).padStart(2, "0")}`;
      q = q.gte("price_date", monthStart).lte("price_date", monthEnd);
    } else {
      q = q.gte("price_date", `${year}-01-01`).lte("price_date", `${year}-12-31`);
    }
  }

  const { data, error } = await q;

  if (error) {
    logLine({ event: "list_failed", error: error.message });
    return c.json({ error: "list_failed", message: error.message }, 500);
  }

  return c.json({
    prices: (data ?? []).map((r) => rowToApi(r as Record<string, unknown>)),
  });
});

app.post("/admin/sync", async (c) => {
  const auth = await requirePlatformAdmin(c);
  if (auth instanceof Response) return auth;
  if (!ADMIN_WRITE_ROLES.has(auth.role)) {
    return c.json({ error: "forbidden", message: "Platform owner required to sync prices" }, 403);
  }

  const body = await c.req.json().catch(() => ({})) as {
    mode?: PetrojamSyncMode;
    year?: number;
    month?: number;
    maxPages?: number;
  };

  const mode: PetrojamSyncMode = body.mode || "latest";
  if (!["latest", "year", "month", "all"].includes(mode)) {
    return c.json({ error: "invalid_mode", message: "mode must be latest|year|month|all" }, 400);
  }

  let fetched: PetrojamFetchResult;
  try {
    fetched = await fetchPetrojamPrices({
      mode,
      year: body.year != null ? Number(body.year) : undefined,
      month: body.month != null ? Number(body.month) : undefined,
      maxPages: body.maxPages != null ? Number(body.maxPages) : undefined,
    });
  } catch (e) {
    const message = e instanceof Error ? e.message : "Scrape failed";
    logLine({ event: "scrape_failed", mode, error: message });
    return c.json({ error: "scrape_failed", message }, 502);
  }

  const scrapedAt = new Date().toISOString();
  let inserted = 0;
  let updated = 0;
  try {
    const result = await upsertScraped(fetched.rows, scrapedAt);
    inserted = result.inserted;
    updated = result.updated;
  } catch (e) {
    const message = e instanceof Error ? e.message : "Upsert failed";
    logLine({ event: "upsert_failed", error: message });
    return c.json({ error: "sync_failed", message }, 500);
  }

  const dates = fetched.rows.map((r) => r.priceDate).sort();
  const latestDate = dates.at(-1) ?? null;
  const oldestDate = dates[0] ?? null;

  logLine({
    event: "sync_ok",
    userId: auth.id,
    mode,
    year: body.year,
    month: body.month,
    inserted,
    updated,
    latestDate,
    oldestDate,
    pagesFetched: fetched.pagesFetched,
    rowCount: fetched.rows.length,
  });

  return c.json({
    ok: true,
    mode,
    year: fetched.year ?? body.year ?? null,
    month: fetched.month ?? body.month ?? null,
    inserted,
    updated,
    latestDate,
    oldestDate,
    pagesFetched: fetched.pagesFetched,
    rowCount: fetched.rows.length,
    scrapedAt,
  });
});

/**
 * Weekly cron / CI: sync latest page using service role or CRON_SECRET.
 * Note: Edge injects new-format sb_secret keys; GitHub often still has legacy eyJ service_role JWT.
 * Accept exact env key match, cron secret, OR a verified legacy service_role JWT.
 */
app.post("/cron/sync-latest", async (c) => {
  const authHeader = c.req.header("Authorization") || "";
  const cronSecret = (Deno.env.get("CRON_SECRET") || Deno.env.get("FLEET_CRON_SECRET") || "").trim();
  const serviceKey = (Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") || "").trim();
  const anonKey = (Deno.env.get("SUPABASE_ANON_KEY") || "").trim();
  const token = authHeader.replace(/^Bearer\s+/i, "").trim();
  const headerCron = (c.req.header("x-fleet-cron-secret") || c.req.header("x-cron-secret") || "").trim();

  const decodeRole = (jwt: string): string => {
    try {
      const part = jwt.split(".")[1];
      if (!part) return "";
      const json = atob(part.replace(/-/g, "+").replace(/_/g, "/"));
      const payload = JSON.parse(json) as { role?: string };
      return typeof payload.role === "string" ? payload.role : "";
    } catch {
      return "";
    }
  };

  /** Prove Bearer is a real service_role JWT (works when env key is sb_* but secret is legacy eyJ). */
  const verifyLegacyServiceRoleJwt = async (jwt: string): Promise<boolean> => {
    if (decodeRole(jwt) !== "service_role") return false;
    const url = (Deno.env.get("SUPABASE_URL") || "").trim();
    if (!url) return false;
    try {
      const client = createClient(url, jwt, {
        auth: { persistSession: false, autoRefreshToken: false },
      });
      const { error } = await client.auth.admin.listUsers({ page: 1, perPage: 1 });
      return !error;
    } catch {
      return false;
    }
  };

  const tokenRole = decodeRole(token);
  const envServiceRole = decodeRole(serviceKey);
  const serviceMatch = !!token && !!serviceKey && token === serviceKey;
  const cronMatch = !!cronSecret && (token === cronSecret || headerCron === cronSecret);
  let legacyJwtOk = false;
  if (!serviceMatch && !cronMatch && token.startsWith("eyJ") && tokenRole === "service_role") {
    legacyJwtOk = await verifyLegacyServiceRoleJwt(token);
  }
  const ok = serviceMatch || cronMatch || legacyJwtOk;
  // #region agent log
  logLine({
    event: "cron_auth_debug",
    hypothesisId: "D",
    sessionId: "560a25",
    runId: "post-fix",
    hasToken: !!token,
    tokenLen: token.length,
    tokenPrefix3: token.slice(0, 3),
    tokenRole,
    hasServiceKey: !!serviceKey,
    serviceKeyLen: serviceKey.length,
    serviceKeyPrefix3: serviceKey.slice(0, 3),
    envServiceRole,
    matchesAnonKey: !!anonKey && token === anonKey,
    serviceMatch,
    cronMatch,
    legacyJwtOk,
  });
  // #endregion
  if (!serviceKey && !cronSecret) {
    logLine({ event: "cron_misconfigured", hypothesisId: "F" });
    return c.json({
      error: "server_misconfigured",
      message: "No SUPABASE_SERVICE_ROLE_KEY or CRON_SECRET in function env",
      debug: { hypothesisId: "F", serviceKeyLen: 0 },
    }, 500);
  }
  if (!ok) {
    logLine({ event: "cron_unauthorized", hasToken: !!token, hasServiceKey: !!serviceKey, hasCronSecret: !!cronSecret });
    // Safe debug in body so GitHub Actions responseTail can confirm root cause
    return c.json({
      error: "unauthorized",
      debug: {
        hypothesisId: "D",
        tokenLen: token.length,
        tokenPrefix3: token.slice(0, 3),
        serviceKeyLen: serviceKey.length,
        serviceKeyPrefix3: serviceKey.slice(0, 3),
        tokenRole,
        envServiceRole,
        matchesAnonKey: !!anonKey && token === anonKey,
        serviceMatch,
        cronMatch,
        legacyJwtOk,
        lensEqual: token.length === serviceKey.length,
      },
    }, 401);
  }

  let fetched: PetrojamFetchResult;
  try {
    fetched = await fetchPetrojamPrices({ mode: "latest" });
  } catch (e) {
    const message = e instanceof Error ? e.message : "Scrape failed";
    logLine({ event: "cron_scrape_failed", error: message });
    return c.json({ error: "scrape_failed", message }, 502);
  }

  const scrapedAt = new Date().toISOString();
  try {
    const { inserted, updated } = await upsertScraped(fetched.rows, scrapedAt);
    const dates = fetched.rows.map((r) => r.priceDate).sort();
    logLine({
      event: "cron_sync_ok",
      inserted,
      updated,
      latestDate: dates.at(-1) ?? null,
      rowCount: fetched.rows.length,
    });
    return c.json({
      ok: true,
      mode: "latest",
      inserted,
      updated,
      latestDate: dates.at(-1) ?? null,
      rowCount: fetched.rows.length,
      scrapedAt,
    });
  } catch (e) {
    const message = e instanceof Error ? e.message : "Upsert failed";
    return c.json({ error: "sync_failed", message }, 500);
  }
});

Deno.serve(app.fetch);

/**
 * Platform Super Admin guard for Edge Functions.
 * DB-backed with JWT fallback during migration.
 */
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { jwtPrimaryRole } from "./authEdge.ts";
import { dbIsPlatformUser } from "./rbacQuery.ts";
import { ROLE_LEVELS } from "./platformPermissions.ts";

export const PLATFORM_ADMIN_ROLES = new Set([
  "platform_owner",
  "platform_support",
  "platform_analyst",
  "superadmin",
]);

export type PlatformAdminUser = { id: string; email: string; role: string };

function authClient(authHeader: string) {
  return createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_ANON_KEY") ?? "",
    { global: { headers: { Authorization: authHeader } } },
  );
}

export async function requirePlatformAdmin(
  c: { req: { header: (n: string) => string | undefined }; json: (b: unknown, s?: number) => Response },
): Promise<PlatformAdminUser | Response> {
  const authHeader = c.req.header("Authorization");
  if (!authHeader?.startsWith("Bearer ")) {
    return c.json({ error: "Unauthorized: missing Authorization header" }, 401);
  }
  const { data: { user }, error } = await authClient(authHeader).auth.getUser();
  if (error || !user) {
    return c.json({ error: "Unauthorized: invalid token" }, 401);
  }

  const isPlatformDb = await dbIsPlatformUser(user.id);
  // Platform access requires DB row — never JWT alone (app_metadata can be stale; user_metadata is spoofable)
  if (!isPlatformDb) {
    return c.json({
      error: "Forbidden",
      message: "Platform admin role required",
      currentRole: jwtPrimaryRole(user) || "(none)",
    }, 403);
  }

  const rawRole = jwtPrimaryRole(user);
  return { id: user.id, email: user.email || "", role: rawRole || "platform_owner" };
}

export function isPlatformAdminRole(role: string): boolean {
  return PLATFORM_ADMIN_ROLES.has(role);
}

export { ROLE_LEVELS };

/**
 * Shared JWT / metadata helpers for Supabase Edge Functions (Deno).
 * Keep responses small and consistent: `{ error: "forbidden" | "forbidden_role" }` at 403.
 */

export type EdgeForbiddenError = "forbidden" | "forbidden_role";

function readRolesArray(meta: Record<string, unknown> | undefined): string[] {
  const raw = meta?.roles;
  if (!Array.isArray(raw)) return [];
  return raw
    .filter((r): r is string => typeof r === "string" && r.trim().length > 0)
    .map((r) => r.trim());
}

export function ridesUserSurfaceRole(user: {
  user_metadata?: Record<string, unknown>;
  app_metadata?: Record<string, unknown>;
}): string | undefined {
  // Prefer app_metadata roles for authz; surface is display-only after Wave 3
  const roles = getJwtRoles(user);
  if (roles.includes("driver")) return "driver";
  if (roles.includes("hauler")) return "hauler";
  if (roles.includes("passenger")) return "passenger";
  const surface = user.user_metadata?.surface;
  if (typeof surface === "string" && surface.trim()) return surface.trim();
  return undefined;
}

/** Passenger app routes — allow passenger JWT role (app_metadata) or unmarked users. */
export function allowsPassengerSurface(user: {
  user_metadata?: Record<string, unknown>;
  app_metadata?: Record<string, unknown>;
}): boolean {
  const roles = getJwtRoles(user);
  if (roles.includes("passenger")) return true;
  if (roles.includes("driver") || roles.includes("hauler")) return false;
  const role = ridesUserSurfaceRole(user);
  if (!role) return true;
  return role === "passenger";
}

/**
 * Driver / hauler dispatch routes — app_metadata roles only.
 * Callers that need profile-backed access should pass hasDriverOrHaulerProfile=true after a DB lookup.
 */
export function allowsHaulerOrDriverSurface(
  user: {
    user_metadata?: Record<string, unknown>;
    app_metadata?: Record<string, unknown>;
  },
  hasDriverOrHaulerProfile = false,
): boolean {
  if (hasDriverOrHaulerProfile) return true;
  const roles = getJwtRoles(user);
  return roles.includes("driver") || roles.includes("hauler");
}

/** Shared gate for contacts, Roam Tag, book-for-others, and related passenger APIs. */
export function deniesPassengerSurface(user: {
  user_metadata?: Record<string, unknown>;
  app_metadata?: Record<string, unknown>;
}): boolean {
  return !allowsPassengerSurface(user);
}

/** True when user has a driver_profiles (or hauler) row — for surface gates. */
export async function hasDriverOrHaulerProfile(
  userId: string,
  lookup: (userId: string) => Promise<boolean>,
): Promise<boolean> {
  return lookup(userId);
}

/**
 * Driver/hauler gate: app_metadata roles OR verified profile via lookup.
 */
export async function allowsHaulerOrDriverSurfaceAsync(
  user: {
    id: string;
    user_metadata?: Record<string, unknown>;
    app_metadata?: Record<string, unknown>;
  },
  profileLookup: (userId: string) => Promise<boolean>,
): Promise<boolean> {
  if (allowsHaulerOrDriverSurface(user)) return true;
  return profileLookup(user.id);
}

/** All roles on JWT from app_metadata only (never user_metadata). */
export function getJwtRoles(user: {
  user_metadata?: Record<string, unknown>;
  app_metadata?: Record<string, unknown>;
}): string[] {
  const fromApp = readRolesArray(user.app_metadata as Record<string, unknown> | undefined);
  if (fromApp.length > 0) return fromApp;
  const primary = jwtPrimaryRole(user);
  return primary ? [primary] : [];
}

/**
 * Primary role: app_metadata.role, else first app_metadata.roles[].
 */
export function jwtPrimaryRole(user: {
  user_metadata?: Record<string, unknown>;
  app_metadata?: Record<string, unknown>;
}): string {
  const appMeta = user.app_metadata as Record<string, unknown> | undefined;
  const explicit = appMeta?.role;
  if (typeof explicit === "string" && explicit.trim()) return explicit.trim();

  const fromArray = readRolesArray(appMeta);
  if (fromArray.length > 0) return fromArray[0];
  return "";
}

export function jsonEdgeForbidden(
  c: { json: (body: unknown, status?: number) => Response },
  kind: EdgeForbiddenError,
  status = 403,
): Response {
  return c.json({ error: kind }, status);
}

/**
 * Database-backed RBAC queries with JWT fallback during migration.
 */
import { createClient, type SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { getJwtRoles, jwtPrimaryRole } from "./authEdge.ts";
import {
  hasProductAdminAccess,
  type ProductKey,
} from "./productAdmin.ts";
import { productPortalAccess } from "./platformPermissions.ts";

export type RbacUser = {
  user_metadata?: Record<string, unknown>;
  app_metadata?: Record<string, unknown>;
};

export function serviceClient(): SupabaseClient {
  return createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "",
  );
}

export async function fetchUserPermissionKeys(userId: string): Promise<string[]> {
  const { data, error } = await serviceClient().rpc("rbac_user_permission_keys", {
    p_user_id: userId,
  });
  if (error) {
    console.warn("[rbac] rbac_user_permission_keys failed:", error.message);
    return [];
  }
  return Array.isArray(data) ? (data as string[]) : [];
}

export async function dbUserHasPermission(
  userId: string,
  permissionKey: string,
): Promise<boolean> {
  const { data, error } = await serviceClient().rpc("rbac_user_has_permission", {
    p_user_id: userId,
    p_permission_key: permissionKey,
  });
  if (error) {
    console.warn("[rbac] rbac_user_has_permission failed:", error.message);
    return false;
  }
  return data === true;
}

export async function dbUserMaxRoleLevel(userId: string): Promise<number> {
  const { data, error } = await serviceClient().rpc("rbac_user_max_role_level", {
    p_user_id: userId,
  });
  if (error) {
    console.warn("[rbac] rbac_user_max_role_level failed:", error.message);
    return 0;
  }
  return typeof data === "number" ? data : 0;
}

export async function dbIsPlatformUser(userId: string): Promise<boolean> {
  const { data, error } = await serviceClient().rpc("rbac_is_platform_user", {
    p_user_id: userId,
  });
  if (error) {
    console.warn("[rbac] rbac_is_platform_user failed:", error.message);
    return false;
  }
  return data === true;
}

export async function dbUserHasProductAccess(
  userId: string,
  product: ProductKey,
): Promise<boolean> {
  const { data, error } = await serviceClient().rpc("rbac_user_has_product_access", {
    p_user_id: userId,
    p_product_key: product,
  });
  if (error) {
    console.warn("[rbac] rbac_user_has_product_access failed:", error.message);
    return false;
  }
  return data === true;
}

/** Resolve permissions: DB first, JWT role mapping as fallback. */
export async function resolveUserPermissions(
  userId: string,
  user: RbacUser,
): Promise<string[]> {
  const fromDb = await fetchUserPermissionKeys(userId);
  if (fromDb.length > 0) return fromDb;

  const roles = getJwtRoles(user);
  const keys = new Set<string>();
  for (const role of roles) {
    keys.add("users.read");
    for (const product of [
      "fleet", "enterprise", "dash", "rides", "driver", "haul", "courier",
    ] as ProductKey[]) {
      if (hasProductAdminAccess(role, product)) {
        keys.add(productPortalAccess(product));
        if (role.endsWith("_admin") || role === "platform_owner" || role === "superadmin") {
          keys.add(`${product}.users.write`);
          keys.add(`${product}.compliance.approve`);
          keys.add(`${product}.support.write`);
          keys.add(`${product}.settings.write`);
        }
        keys.add(`${product}.users.read`);
        keys.add(`${product}.compliance.read`);
        keys.add(`${product}.ledger.read`);
        keys.add(`${product}.presence.read`);
        keys.add(`${product}.settings.read`);
      }
    }
    if (role === "platform_owner" || role === "superadmin") {
      keys.add("users.read");
      keys.add("analytics.view");
      keys.add("system.config");
      keys.add("audit.read");
    }
  }
  return [...keys];
}

export async function userHasPermissionResolved(
  userId: string,
  user: RbacUser,
  permissionKey: string,
): Promise<boolean> {
  const fromDb = await dbUserHasPermission(userId, permissionKey);
  if (fromDb) return true;

  const perms = await resolveUserPermissions(userId, user);
  if (perms.includes(permissionKey)) return true;

  const roles = getJwtRoles(user);
  if (roles.length === 0) return false;

  if (permissionKey.endsWith(".portal.access")) {
    const product = permissionKey.replace(".portal.access", "") as ProductKey;
    return roles.some((r) => hasProductAdminAccess(r, product));
  }
  return false;
}

export async function userHasProductAccessResolved(
  userId: string,
  user: RbacUser,
  product: ProductKey,
): Promise<boolean> {
  const fromDb = await dbUserHasProductAccess(userId, product);
  if (fromDb) return true;
  return getJwtRoles(user).some((r) => hasProductAdminAccess(r, product));
}

/** Active platform role names from DB (honours expires_at). */
export async function fetchUserRoleNames(userId: string): Promise<string[]> {
  const now = new Date().toISOString();
  const { data, error } = await serviceClient()
    .schema("platform")
    .from("user_roles")
    .select("expires_at, roles(name)")
    .eq("user_id", userId);
  if (error) {
    console.warn("[rbac] fetchUserRoleNames failed:", error.message);
    return [];
  }
  const names: string[] = [];
  for (const row of data ?? []) {
    const expiresAt = (row as { expires_at?: string | null }).expires_at;
    if (expiresAt && expiresAt <= now) continue;
    const role = (row as { roles?: { name?: string } | { name?: string }[] | null }).roles;
    const roleObj = Array.isArray(role) ? role[0] : role;
    const name = roleObj?.name;
    if (name) names.push(name);
  }
  return [...new Set(names)];
}

/** Merge JWT roles with DB-granted roles (DB wins for write gates). */
export async function resolveEffectiveRoleNames(
  userId: string,
  user: RbacUser,
): Promise<string[]> {
  const jwtRoles = getJwtRoles(user);
  const dbRoles = await fetchUserRoleNames(userId);
  if (dbRoles.length === 0) return jwtRoles;
  return [...new Set([...jwtRoles, ...dbRoles])];
}
